bootstrap();

async function bootstrap() {
  try {
    if (isPublicView) {
      await loadPublicWorkspace();
      startPolling();
    } else {
      await checkAuth();
      if (authState.requiresPassword && !authState.authenticated) {
        renderLogin();
        return;
      }
      await loadOwnerWorkspace();
      await loadBackups(false);
    }
    restoreEmployeeViewState();
    render();
  } catch (error) {
    if (error.message === "AUTH_REQUIRED") return;
    workspace = loadLocalWorkspace();
    restoreEmployeeViewState();
    render();
    showToast("Сервер недоступен, изменения сохраняются только в этом браузере");
  }
}

async function checkAuth() {
  if (!canUseServer || isPublicView) return;
  const response = await fetch("/api/auth", { cache: "no-store" });
  if (!response.ok) return;
  authState = await response.json();
}

async function loadOwnerWorkspace() {
  if (!canUseServer) {
    workspace = loadLocalWorkspace();
    return;
  }

  const response = await fetch("/api/workspace", { cache: "no-store" });
  if (response.status === 401) {
    authState = { requiresPassword: true, authenticated: false };
    renderLogin();
    throw new Error("AUTH_REQUIRED");
  }
  if (!response.ok) throw new Error("Не удалось загрузить данные");
  const payload = await response.json();
  workspace = mergeWorkspace(payload.workspace);
  shareUrl = payload.shareUrl || "";
  editorUrl = payload.editorUrl || location.origin + "/";
  publicViewBaseUrl = payload.publicViewBaseUrl || "";

  const pendingWorkspace = readPendingWorkspace();
  if (pendingWorkspace) {
    workspace = mergeWorkspace(pendingWorkspace);
    const recovered = await saveWorkspace(true);
    if (recovered) showToast("Несохраненные изменения восстановлены");
  }
}

async function loadPublicWorkspace() {
  const response = await fetch(`/api/public/${publicToken}`, { cache: "no-store" });
  if (!response.ok) throw new Error("Ссылка недоступна");
  const payload = await response.json();
  workspace = mergeWorkspace(payload.workspace);
  lastSavedAt = payload.updatedAt || workspace.updatedAt || "";
}

function loadLocalWorkspace() {
  try {
    const stored = localStorage.getItem(PENDING_WORKSPACE_KEY) || localStorage.getItem(LOCAL_WORKSPACE_KEY);
    return mergeWorkspace(stored ? JSON.parse(stored) : DEFAULT_WORKSPACE);
  } catch (error) {
    return mergeWorkspace(DEFAULT_WORKSPACE);
  }
}

function readPendingWorkspace() {
  try {
    const stored = localStorage.getItem(PENDING_WORKSPACE_KEY);
    return stored ? JSON.parse(stored) : null;
  } catch (error) {
    try {
      localStorage.removeItem(PENDING_WORKSPACE_KEY);
    } catch (innerError) {
      // Local storage cleanup is optional.
    }
    return null;
  }
}

function cacheWorkspaceLocally(value, pending = false) {
  try {
    const serialized = JSON.stringify(value);
    localStorage.setItem(LOCAL_WORKSPACE_KEY, serialized);
    if (pending) localStorage.setItem(PENDING_WORKSPACE_KEY, serialized);
  } catch (error) {
    // Large attachments can exceed browser storage; server save remains the source of truth.
  }
}

function clearPendingWorkspace() {
  try {
    localStorage.removeItem(PENDING_WORKSPACE_KEY);
  } catch (error) {
    // Local storage cleanup is optional.
  }
}

function mergeWorkspace(source) {
  const merged = clone(DEFAULT_WORKSPACE);
  const incoming = source && typeof source === "object" ? source : {};

  merged.title = incoming.title || merged.title;
  merged.period = incoming.period || merged.period;
  merged.updatedAt = incoming.updatedAt || merged.updatedAt;

  for (const item of SECTIONS) {
    if (incoming.sections && incoming.sections[item.id]) {
      merged.sections[item.id] = {
        ...merged.sections[item.id],
        ...incoming.sections[item.id]
      };
    }
  }

  upgradeCalendarData(merged);
  return merged;
}

function upgradeCalendarData(target) {
  const fallbackMonth = "2026-06";
  const roadmap = target.sections.roadmap;
  roadmap.calendarMonth = validMonthValue(roadmap.calendarMonth) ? roadmap.calendarMonth : fallbackMonth;
  roadmap.hiddenMonths = Array.isArray(roadmap.hiddenMonths) ? roadmap.hiddenMonths.filter(validMonthValue) : [];
  roadmap.deletedMonthIds = Array.isArray(roadmap.deletedMonthIds) ? roadmap.deletedMonthIds.filter(Boolean).slice(-1000) : [];
  (roadmap.months || []).forEach((item, index) => {
    if (!validDateValue(item.date)) {
      item.date = `${target.period || "2026"}-${String((index % 12) + 1).padStart(2, "0")}-01`;
    }
    if (!item.id) item.id = `roadmap-${index}-${normalizeName(item.task || item.month) || newId("m")}`;
    if (!item.updatedAt) item.updatedAt = roadmap.updatedAt || target.updatedAt;
    item.fieldUpdatedAt = normalizeItemFieldTimestamps(item, ROADMAP_ITEM_FIELDS);
  });

  const content = target.sections.content;
  content.calendarMonth = validMonthValue(content.calendarMonth) ? content.calendarMonth : fallbackMonth;
  content.hiddenMonths = Array.isArray(content.hiddenMonths) ? content.hiddenMonths.filter(validMonthValue) : [];
  content.deletedWeekIds = Array.isArray(content.deletedWeekIds) ? content.deletedWeekIds.filter(Boolean).slice(-500) : [];
  content.deletedItemIds = Array.isArray(content.deletedItemIds) ? content.deletedItemIds.filter(Boolean).slice(-1000) : [];
  (content.weeks || []).forEach((week, weekIndex) => {
    if (!week.id) week.id = `content-week-${weekIndex}-${normalizeName(week.title) || newId("w")}`;
    if (!week.updatedAt) week.updatedAt = content.updatedAt || target.updatedAt;
    week.fieldUpdatedAt = normalizeItemFieldTimestamps(week, CONTENT_WEEK_FIELDS);
    (week.items || []).forEach((item, itemIndex) => {
      if (!validDateValue(item.date)) {
        const day = Math.min(28, 1 + weekIndex * 7 + itemIndex);
        item.date = `${content.calendarMonth}-${String(day).padStart(2, "0")}`;
      }
      if (!item.id) item.id = `content-item-${week.id}-${itemIndex}-${normalizeName(item.title) || newId("c")}`;
      if (!item.updatedAt) item.updatedAt = week.updatedAt || content.updatedAt || target.updatedAt;
      item.fieldUpdatedAt = normalizeItemFieldTimestamps(item, CONTENT_ITEM_FIELDS);
      item.types = normalizeContentTypes(item);
      item.type = item.types[0] || "";
    });
  });

  const board = target.sections.board;
  board.projects = Array.isArray(board.projects) ? board.projects : [];
  board.deletedProjectIds = Array.isArray(board.deletedProjectIds) ? board.deletedProjectIds.filter(Boolean).slice(-1000) : [];
  const firstProjectMonth = board.projects
    .map(project => project.due)
    .filter(validDateValue)
    .map(monthFromDate)
    .sort()[0];
  board.calendarMonth = validMonthValue(board.calendarMonth) ? board.calendarMonth : firstProjectMonth || fallbackMonth;
  board.stages = BOARD_STAGES;
  board.categories = normalizeBoardCategories([
    ...DEFAULT_BOARD_CATEGORIES,
    ...(Array.isArray(board.categories) ? board.categories : []),
    ...board.projects.map(project => project.category)
  ]);
  board.categoryColors = board.categoryColors && typeof board.categoryColors === "object"
    ? { ...DEFAULT_BOARD_CATEGORY_COLORS, ...board.categoryColors }
    : { ...DEFAULT_BOARD_CATEGORY_COLORS };
  board.collapsedCategories = board.collapsedCategories && typeof board.collapsedCategories === "object"
    ? board.collapsedCategories
    : {};
  board.projects.forEach((project, projectIndex) => {
    if (!project.id) project.id = `project-${normalizeName(project.title) || newId("p")}`;
    if (!project.updatedAt) project.updatedAt = board.updatedAt || target.updatedAt;
    project.fieldUpdatedAt = normalizeItemFieldTimestamps(project, BOARD_PROJECT_FIELDS);
    project.stage = normalizeBoardStage(project.stage);
    project.category = normalizeBoardCategory(project.category, board.categories);
    if (!Number.isFinite(Number(project.order))) project.order = projectIndex;
    if (!validDateValue(project.due)) project.due = `${board.calendarMonth}-01`;
  });

  const project2 = target.sections.project2 || (target.sections.project2 = {});
  project2.initialized = Boolean(project2.initialized && (Array.isArray(project2.tasks) || Array.isArray(project2.backlog)));
  project2.people = Array.isArray(project2.people) ? project2.people : [];
  project2.categories = Array.isArray(project2.categories) ? project2.categories : [];
  project2.tasks = Array.isArray(project2.tasks) ? project2.tasks : [];
  project2.backlog = Array.isArray(project2.backlog) ? project2.backlog : [];
  project2.filters = project2.filters && typeof project2.filters === "object" ? project2.filters : {};
  project2.updatedAt = project2.updatedAt || target.updatedAt || new Date().toISOString();

  const employees = target.sections.employees;
  employees.month = validMonthValue(employees.month) ? employees.month : fallbackMonth;
  employees.taskFilter = EMPLOYEE_TASK_FILTERS.some(item => item.value === employees.taskFilter) ? employees.taskFilter : "none";
  employees.deletedEmployeeIds = Array.isArray(employees.deletedEmployeeIds) ? employees.deletedEmployeeIds.filter(Boolean).slice(-500) : [];
  employees.deletedReportIds = Array.isArray(employees.deletedReportIds) ? employees.deletedReportIds.filter(Boolean).slice(-1000) : [];
  employees.people = Array.isArray(employees.people) ? employees.people : [];
  employees.people.forEach((person, personIndex) => {
    if (!person.id) person.id = `employee-${personIndex}-${normalizeName(person.name) || newId("person")}`;
    if (!person.updatedAt) person.updatedAt = employees.updatedAt || target.updatedAt;
    person.reports = Array.isArray(person.reports) ? person.reports : [];
    person.reports.forEach((report, reportIndex) => {
      if (!report.id) report.id = `report-${person.id}-${reportIndex}-${normalizeName(report.title) || newId("task")}`;
      if (!report.updatedAt) report.updatedAt = person.updatedAt || employees.updatedAt || target.updatedAt;
      report.attachments = normalizeReportAttachments(report.attachments);
      report.fieldUpdatedAt = normalizeReportFieldTimestamps(report);
    });
  });
  const employeeReports = (employees.people || []).flatMap(person => person.reports || []);
  employeeReports.forEach(report => {
    if (!REPORT_STATUSES.some(status => status.value === report.status)) {
      report.status = report.completed ? "done" : "plan";
    }
    report.completed = report.status === "done";
  });
  if (validDateValue(employees.day)) {
    employees.month = monthFromDate(employees.day) || employees.month;
  } else {
    const firstReportInMonth = employeeReports
      .map(report => report.date)
      .filter(date => validDateValue(date) && monthFromDate(date) === employees.month)
      .sort()[0];
    employees.day = firstReportInMonth || `${employees.month}-01`;
  }}


function syncProject2DoneReportsToEmployees() {
  if (!workspace?.sections?.employees) return false;
  let doneTasks = [];
  try { doneTasks = JSON.parse(localStorage.getItem(PROJECT2_DONE_REPORTS_KEY) || "[]"); } catch (error) { doneTasks = []; }
  if (!Array.isArray(doneTasks) || !doneTasks.length) return false;
  const people = workspace.sections.employees.people || [];
  let changed = false;
  const time = new Date().toISOString();
  doneTasks.forEach(task => {
    if (!task || task.status !== "Выполнено" || !task.assignee) return;
    const person = people.find(item => normalizeName(item.name) === normalizeName(task.assignee));
    if (!person) return;
    person.reports = Array.isArray(person.reports) ? person.reports : [];
    const reportId = `project2-${task.id}`;
    const reportDate = validDateValue(task.date) ? task.date : dateValue(new Date());
    const title = `#${task.number || ""} ${task.title || "Задача из Доски проектов 2"}`.replace(/#\s+/, "").trim();
    const text = task.description ? `Из Доски проектов 2.\n\n${task.description}` : "Из Доски проектов 2.";
    let report = person.reports.find(item => String(item.id) === reportId);
    if (!report) {
      report = { id: reportId, title, text, date: reportDate, status: "done", completed: true, attachments: [], createdAt: time, updatedAt: time };
      person.reports.push(report);
      changed = true;
    } else {
      const next = { title, text, date: reportDate, status: "done", completed: true };
      for (const [key, value] of Object.entries(next)) {
        if (report[key] !== value) { report[key] = value; changed = true; }
      }
    }
    if (changed) touchReportRecord(report, person, ["title", "text", "date", "status"], time);
  });
  if (changed) { touch("employees"); saveWorkspace(); }
  return changed;
}

