function sendProject2StateToFrame() {
  const frameWindow = project2Frame();
  if (!frameWindow) return;
  frameWindow.postMessage({ type: "project2-state-missing", state: null }, "*");
}

function project2SharedTaskKey(task) {
  return String(task?.id || task?.number || task?.title || "");
}

function mergeProject2SharedList(current = [], incoming = []) {
  const items = new Map();
  (Array.isArray(current) ? current : []).forEach(item => {
    const key = project2SharedTaskKey(item);
    if (key) items.set(key, item);
  });
  (Array.isArray(incoming) ? incoming : []).forEach(item => {
    const key = project2SharedTaskKey(item);
    if (key) items.set(key, { ...(items.get(key) || {}), ...item });
  });
  return Array.from(items.values()).sort((a, b) => (Number(a.number) || 0) - (Number(b.number) || 0));
}

function mergeProject2SharedState(current = {}, incoming = {}) {
  return {
    ...current,
    ...incoming,
    people: Array.isArray(incoming.people) && incoming.people.length ? incoming.people : current.people,
    categories: Array.isArray(incoming.categories) && incoming.categories.length ? incoming.categories : current.categories,
    tasks: mergeProject2SharedList(current.tasks, incoming.tasks),
    backlog: mergeProject2SharedList(current.backlog, incoming.backlog),
    filters: { ...(current.filters || {}), ...(incoming.filters || {}) },
    initialized: true,
    updatedAt: new Date().toISOString()
  };
}

function saveProject2SharedState(state) {
  if (isPublicView || !workspace?.sections || !state || typeof state !== "object") return;
  workspace.sections.project2 = clone(state);
  touch("project2", false);
  saveWorkspace();
}
